class Solution {
public:
    int smallestValue(int n) {
        while (true) {
            int sum = primeFactorSum(n);
            if (sum == n) break;
            n = sum;
        }
        return n;
    }
private:
    int primeFactorSum(int n) {
        int sum = 0;
        int x = n;
        for (int d = 2; d * d <= x; d++) {
            while (x % d == 0) {
                sum += d;
                x /= d;
            }
        }
        if (x > 1) sum += x;
        return sum;
    }
};
